-- resolve-pilot live bridge (protocol 2), generated by resolve-pilot __RP_VERSION_TEXT__
--
-- Lets the resolve-pilot MCP server run Lua inside DaVinci Resolve, including the
-- FREE edition, where external scripting is disabled. Start it ONE of two ways:
--   * Workspace > Scripts > ResolvePilotBridge (installed by the `setup_bridge` tool), or
--   * Workspace > Console > "Lua" tab: paste this whole file and press Enter.
-- It stops by itself after __RP_IDLE_MIN__ minutes without requests, when the MCP server
-- asks it to, or when another copy of the bridge starts (the newest one wins).
--
-- Protocol: plain files in DIR. Both sides write a temp file and rename it.
--   request.lua    host -> bridge   line 1 "-- rp-id: <id>", then the Lua to run
--   response.json  bridge -> host   {"id", "ok", "output", "result", "error"}
--   heartbeat      bridge -> host   "<epoch> <version> <token>", refreshed every ~2 s
--   stop           host -> bridge   its presence makes the bridge exit

local DIR = __RP_BRIDGE_DIR__
local VERSION = __RP_VERSION__
local IDLE_LIMIT = __RP_IDLE_SECONDS__
local TICK = 0.2

local SEP = package.config:sub(1, 1)
local REQ = DIR .. SEP .. "request.lua"
local RESP = DIR .. SEP .. "response.json"
local BEAT = DIR .. SEP .. "heartbeat"
local STOP = DIR .. SEP .. "stop"
local log = print

local function read_file(path)
  local f = io.open(path, "rb")
  if not f then return nil end
  local s = f:read("*a")
  f:close()
  return s
end

local function write_atomic(path, content)
  local tmp = path .. ".tmp"
  local f = io.open(tmp, "wb")
  if not f then return false end
  f:write(content)
  f:close()
  os.remove(path) -- Windows cannot rename onto an existing file
  return os.rename(tmp, path) and true or false
end

local function sleep(sec)
  if bmd and bmd.wait then bmd.wait(sec) return end
  if SEP == "/" then os.execute("sleep " .. sec) return end
  local t = os.clock() + sec
  while os.clock() < t do end
end

-- JSON encoding ------------------------------------------------------------

local ESC = {
  ['"'] = '\\"', ["\\"] = "\\\\", ["\b"] = "\\b", ["\f"] = "\\f",
  ["\n"] = "\\n", ["\r"] = "\\r", ["\t"] = "\\t",
}

local function json_string(s)
  return '"' .. s:gsub('[%c"\\]', function(c)
    return ESC[c] or string.format("\\u%04x", c:byte())
  end) .. '"'
end

local function is_array(t)
  local n = 0
  for k in pairs(t) do
    if type(k) ~= "number" or k < 1 or k ~= math.floor(k) then return false, 0 end
    n = n + 1
  end
  for i = 1, n do
    if t[i] == nil then return false, 0 end
  end
  return true, n
end

local function json_value(v, depth)
  local t = type(v)
  if v == nil then return "null" end
  if t == "boolean" then return v and "true" or "false" end
  if t == "number" then
    if v ~= v or v == math.huge or v == -math.huge then return "null" end
    if v == math.floor(v) and math.abs(v) < 1e15 then return string.format("%d", v) end
    return string.format("%.14g", v)
  end
  if t == "string" then return json_string(v) end
  if t == "table" then
    if depth > 32 then return json_string("<nested too deep>") end
    local parts = {}
    local arr, n = is_array(v)
    if arr then
      for i = 1, n do parts[i] = json_value(v[i], depth + 1) end
      return "[" .. table.concat(parts, ",") .. "]"
    end
    local keys = {}
    for k in pairs(v) do keys[#keys + 1] = k end
    table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
    for _, k in ipairs(keys) do
      parts[#parts + 1] = json_string(tostring(k)) .. ":" .. json_value(v[k], depth + 1)
    end
    return "{" .. table.concat(parts, ",") .. "}"
  end
  return json_string(tostring(v)) -- Resolve objects (userdata), functions
end

local function show(v)
  if type(v) == "table" then return json_value(v, 0) end
  return tostring(v)
end

-- Helpers available to request code as the global `rp` ----------------------

local function get_resolve()
  if resolve then return resolve end
  if type(Resolve) == "function" then
    local ok, r = pcall(Resolve)
    if ok and r then return r end
  end
  return nil
end

if not resolve then resolve = get_resolve() end

rp = {
  version = VERSION,
  json = function(v) return json_value(v, 0) end,
  resolve = get_resolve,
}

function rp.project()
  local r = get_resolve()
  local p = r and r:GetProjectManager():GetCurrentProject()
  if not p then error("No project is open in Resolve.", 2) end
  return p
end

function rp.timeline()
  local tl = rp.project():GetCurrentTimeline()
  if not tl then error("No active timeline. Open a timeline on the Edit page first.", 2) end
  return tl
end

function rp.media_pool()
  return rp.project():GetMediaPool()
end

function rp.fps()
  return tonumber(rp.timeline():GetSetting("timelineFrameRate"))
    or tonumber(rp.project():GetSetting("timelineFrameRate")) or 24
end

-- Request handling ---------------------------------------------------------

local function handle(raw)
  local resp = { id = raw:match("^%-%- rp%-id: ([%w%-_]+)") or "" }
  local captured = {}
  local function capture(...)
    local row = {}
    for i = 1, select("#", ...) do row[i] = show((select(i, ...))) end
    captured[#captured + 1] = table.concat(row, "\t")
  end
  local fn, perr = (loadstring or load)(raw, "=request")
  if not fn then
    resp.ok = false
    resp.error = "Lua syntax error: " .. tostring(perr)
  else
    local real_print = print
    print = capture
    local ok, value = xpcall(fn, debug.traceback)
    print = real_print
    resp.ok = ok
    if ok then resp.result = value else resp.error = tostring(value) end
  end
  resp.output = table.concat(captured, "\n")
  if not write_atomic(RESP, json_value(resp, 0)) then
    log("[bridge] could not write " .. RESP)
  end
end

-- Main loop ----------------------------------------------------------------

-- os.time() alone repeats when two bridges start in the same second; a fresh
-- table's address differs per process, which keeps tokens unique.
local ADDR = tostring({}):match("0x(%x+)") or tostring(os.clock())
math.randomseed(os.time() + (tonumber(ADDR:sub(-6), 16) or 0))
local TOKEN = os.time() .. "-" .. ADDR .. "-" .. math.random(100000, 999999)

local function heartbeat()
  return write_atomic(BEAT, os.time() .. " " .. VERSION .. " " .. TOKEN)
end

local function superseded()
  local s = read_file(BEAT)
  return s ~= nil and not s:find(TOKEN, 1, true)
end

os.remove(REQ)
os.remove(RESP)
os.remove(STOP)
if not heartbeat() then
  os.execute((SEP == "/" and 'mkdir -p "' or 'mkdir "') .. DIR .. '"')
  if not heartbeat() then
    log("[bridge] ERROR: cannot write to " .. DIR)
    log("[bridge] Make sure the folder is writable. The Mac App Store build of Resolve is " ..
      "sandboxed and cannot reach it; use the download from blackmagicdesign.com.")
    return
  end
end

log("[bridge] resolve-pilot bridge " .. VERSION .. " ready. Folder: " .. DIR)
if not resolve then
  log("[bridge] WARNING: no 'resolve' object here. Run this from Resolve's Console or Workspace > Scripts.")
end
log(string.format("[bridge] Leave Resolve open and talk to Claude. Stops after %d min without requests.",
  math.floor(IDLE_LIMIT / 60)))

local last_activity = os.time()
local tick = 0
local reason = "idle timeout"
while true do
  tick = tick + 1
  if read_file(REQ) then
    if superseded() then reason = "another bridge started"; break end
    local req = read_file(REQ)
    os.remove(REQ)
    if req then handle(req) end
    last_activity = os.time()
    heartbeat()
  end
  if tick % 10 == 0 then
    if read_file(STOP) then
      os.remove(STOP)
      reason = "stop requested"
      break
    end
    if superseded() then reason = "another bridge started"; break end
    heartbeat()
  end
  if os.time() - last_activity > IDLE_LIMIT then break end
  sleep(TICK)
end

if not superseded() then os.remove(BEAT) end
log("[bridge] stopped (" .. reason .. ").")
